import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"賁","description":"焦氏易林注 - 賁","frontmatter":{"title":"賁","description":"焦氏易林注 - 賁"},"headers":[],"relativePath":"classics/jiaoyilin/022.md","filePath":"classics/jiaoyilin/022.md"}'),l={name:"classics/jiaoyilin/022.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="賁" tabindex="-1">賁 <a class="header-anchor" href="#賁" aria-label="Permalink to “賁”">​</a></h1><h3 id="賁-1" tabindex="-1">賁 <a class="header-anchor" href="#賁-1" aria-label="Permalink to “賁”">​</a></h3><h3 id="賁之乾" tabindex="-1">賁之乾 <a class="header-anchor" href="#賁之乾" aria-label="Permalink to “賁之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>八口九頭，長舌破家。帝辛沈湎，商滅其墟。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此用《賁》卦象。震為口，艮數八，故曰八口。乾為首，數九，故曰九頭。帝辛，紂也。震為帝，伏兌為秋。《月令》：&quot;秋，其味辛，其音商。&quot;故曰帝辛。互坎，故曰沈湎。艮為虛，坎伏，故曰滅。長舌指賁下震。兌為舌，震形長於兌，故曰長舌，謂妲已。艮為家，坎為破，故曰破家。</p><h3 id="賁之坤" tabindex="-1">賁之坤 <a class="header-anchor" href="#賁之坤" aria-label="Permalink to “賁之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>鬼守我門，呼伯入山。去其室家，舍其兆墓。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>此亦用《賁》象。坎為鬼，艮為門，震為伯，為呼。艮為山、為墓、為舍，坎為室。○舍，依宋元本，汲古作舍。坤為兆，《孝經》&quot;卜其宅兆而安厝之&quot;，註：塋墓界域曰兆。舍，居也。</p><h3 id="賁之屯" tabindex="-1">賁之屯 <a class="header-anchor" href="#賁之屯" aria-label="Permalink to “賁之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>日出阜東，山蔽其明。章甫薦屨，箕子徉狂。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>艮為山阜，震為東，離伏故明。蔽艮為冠、為章甫。震為屨、為草。薦，草也。震為箕、為子、為狂，上朝服下草履不類，故曰狂。○屨，依宋元本，汲古作履。</p><h3 id="賁之蒙" tabindex="-1">賁之蒙 <a class="header-anchor" href="#賁之蒙" aria-label="Permalink to “賁之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>戴盆望天，不見星辰。願小失大，福逃牆外。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>震為盆，艮為戴、為天、為望、為星辰，坎隱，故不見。艮為小，震為大，坎失，故曰失大。震為福，艮為牆。</p><h3 id="賁之需" tabindex="-1">賁之需 <a class="header-anchor" href="#賁之需" aria-label="Permalink to “賁之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>兩輪並轉，南山大阪。四馬共轅，無有重難，與語笑言。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>坎為輪，兌卦數二，故曰兩輪。離為南，乾為山、為阪、為馬，兌數四，故曰四馬。兌為笑言。轅象似指坎。坎為棟，故為轅。古牛車兩轅，馬車一轅。轅，左右各兩馬，轅居正中。正《坎》象也。○並轉，汲古作日轉，依宋元本。</p><h3 id="賁之訟" tabindex="-1">賁之訟 <a class="header-anchor" href="#賁之訟" aria-label="Permalink to “賁之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>羊驚狼虎，聳耳群聚。行旅稽難，流連愁苦。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>此用《賁》象。震為羊，艮為狼虎，震為驚，故曰羊驚狼虎。坎為耳、為眾，故曰群聚。震為行旅，艮止，故曰稽難，坎陷，故曰流連、曰愁苦。全用遇卦象。</p><h3 id="賁之師" tabindex="-1">賁之師 <a class="header-anchor" href="#賁之師" aria-label="Permalink to “賁之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>楩生荊山，命制輪班。袍衣剝脫，夏熱冬寒。饑餓枯槁，眾人莫憐。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>詳《大有》之《未濟》。 ○楩，汲古作梗，非。</p><h3 id="賁之比" tabindex="-1">賁之比 <a class="header-anchor" href="#賁之比" aria-label="Permalink to “賁之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>鳥飛無翼，兔走折足。不常其德，自為羞辱。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>艮為鳥，震為兔、為翼、為足，震覆故無翼、故折足。又震為德，震覆，故曰不常其德。坤為羞辱。</p><h3 id="賁之小畜" tabindex="-1">賁之小畜 <a class="header-anchor" href="#賁之小畜" aria-label="Permalink to “賁之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>條風制氣，萬物出生。明庶長養，花葉茂榮。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>巽為風、為氣，巽木，故曰條風。乾為生，伏坤為萬物，兌為花。《史記律書》：&quot;條風居東北，主生萬物，故曰長養&quot;。 ○出生，依汲古，宋元本作生出。茂榮，宋元本、汲古皆作壯茂，依局本。</p><h3 id="賁之履" tabindex="-1">賁之履 <a class="header-anchor" href="#賁之履" aria-label="Permalink to “賁之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>坤厚地德，庶物蕃息。平康正直，以綏大福。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>通《謙》。坤為厚、為庶物，震為蕃息，坎為平正，乾為直、為大福。○庶，汲古作萬，依宋元本。</p><h3 id="賁之泰" tabindex="-1">賁之泰 <a class="header-anchor" href="#賁之泰" aria-label="Permalink to “賁之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>昴畢附耳，將軍乘怒。徑路隔塞，燕雀驚駭。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>伏艮為星，故曰昴畢附耳，皆星名也。震為武人，故為將軍、為怒、為徑路，坤閉，故曰隔塞。兌燕雀，震為驚駭。翟雲升《天官書》：&quot;昴主旄頭，畢主邊兵，其大星旁有小星曰附耳，動搖，主有讒亂臣在側&quot;。 ○乘，依汲古，宋元本作求怒，非。</p><h3 id="賁之否" tabindex="-1">賁之否 <a class="header-anchor" href="#賁之否" aria-label="Permalink to “賁之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>東風啟戶，黔啄翻舞。各樂其類，鹹得生處。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>巽風艮戶，艮為黔啄、為翻舞，六爻皆有應與，故曰各樂其類。○啄，無論何本皆同，是焦讀黔喙為黔啄，專主鳥象。</p><h3 id="賁之同人" tabindex="-1">賁之同人 <a class="header-anchor" href="#賁之同人" aria-label="Permalink to “賁之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>兩足四翼，飛入家國。寧我伯姊，與母相得。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>通《師》。震為足，坤數二，故曰兩足。震為翼，卦數四，故曰四翼。坤為我、為國，震為伯，巽為姊，故曰伯姊。坤為母。</p><h3 id="賁之大有" tabindex="-1">賁之大有 <a class="header-anchor" href="#賁之大有" aria-label="Permalink to “賁之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>歲暮花落，陽入陰室。萬物伏匿，藏不可得。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>通《比》。坤為歲、為暮，兌為花，兌毀故落。坎為室，九五居群陰之中故曰陽入陰室。坤為萬物，坎為伏，故曰匿、曰藏。○藏，依宋元本，汲古作歲。</p><h3 id="賁之謙" tabindex="-1">賁之謙 <a class="header-anchor" href="#賁之謙" aria-label="Permalink to “賁之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>釋然遠咎，避患高阜。田獲三狐，以貝為寶。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>坤為咎，在外故曰遠。坤為患害，在外故曰避。艮山故曰高阜。震為田，艮為狐，震數三，故曰三狐。艮為貝，震為寶。○高阜，依汲古，宋元本作害早，系形訛。汲古寶下多&quot;君子所在，安寧不殆&quot;二句，宋元本無。</p><h3 id="賁之豫" tabindex="-1">賁之豫 <a class="header-anchor" href="#賁之豫" aria-label="Permalink to “賁之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>遷延卻縮，不見頭目。日以困急，不能自復。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>艮止故遷延卻縮。乾為頭，離為目，乾離皆伏故不見。坎為困急，地雷《復》，今雷在上故不能復。○遷，宋元本作鵲，依汲古。不能自復，汲古無，依宋元本添。目復為韻，故知汲古非。</p><h3 id="賁之隨" tabindex="-1">賁之隨 <a class="header-anchor" href="#賁之隨" aria-label="Permalink to “賁之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>秋隼冬翔，數被嚴霜。雞犬夜鳴，家擾不寧。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>兌秋艮隼，互大坎故曰冬、曰霜。巽為雞，艮為犬，震為鳴，兌為夜，故曰雞犬夜鳴。艮為家，震為驚擾。○雞，依宋元本，汲古作雄，非。</p><h3 id="賁之蠱" tabindex="-1">賁之蠱 <a class="header-anchor" href="#賁之蠱" aria-label="Permalink to “賁之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>班馬還師，以息勞疲。役夫嘉喜，入戶見妻。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>此用《賁》象。震為馬、為反，故曰班馬、曰還師。坎為勞，艮止，故曰以息勞疲。震為夫、為喜，艮為戶，巽為入，震巽為夫婦，故入戶見妻。○戶，依宋元本，汲古作室，亦可從。</p><h3 id="賁之臨" tabindex="-1">賁之臨 <a class="header-anchor" href="#賁之臨" aria-label="Permalink to “賁之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>老楊日衰，條多枯枝。爵級不進，逐下摧隤。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>震為楊，坤敝，故曰老楊。伏巽故曰枯。震為爵。《左傳》不行之謂臨，故曰不進。坤喪兌毀，故曰摧隤。震為逐，坤為下，逐下者，言漸流而下也。○逐下，依宋元本，汲古作遂至。</p><h3 id="賁之噬嗑" tabindex="-1">賁之噬嗑 <a class="header-anchor" href="#賁之噬嗑" aria-label="Permalink to “賁之噬嗑”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>六人俱行，各遺其囊。黃鵠失珠，無以為明。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>詳《臨》之《師》。 ○鵠，宋元本作鶴。</p><h3 id="賁之賁" tabindex="-1">賁之賁 <a class="header-anchor" href="#賁之賁" aria-label="Permalink to “賁之賁”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>仁政不暴，鳳凰來舍。四時順節，民安其居。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>震仁坎和，故曰不暴。離為鳳凰，艮為舍，震春、離夏、坎冬，伏兌為秋，故曰四時順節。艮為節。坎為民，艮為安、為居。○首句依汲古，宋元作政不暴虐。</p><h3 id="賁之剝" tabindex="-1">賁之剝 <a class="header-anchor" href="#賁之剝" aria-label="Permalink to “賁之剝”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>依叔牆隅，志下心勞。楚亭晨食，韓子低頭。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>詳《同人》之《震》。第二三句依汲古，宋元本作&quot;志下勞苦，楚相辰食&quot;，非，此用韓信寄食亭長事，勞與頭古協。</p><h3 id="賁之復" tabindex="-1">賁之復 <a class="header-anchor" href="#賁之復" aria-label="Permalink to “賁之復”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>三牛生狗，以戌為母。荊夷上侵，姬伯出走。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《震》。</p><h3 id="賁之無妄" tabindex="-1">賁之無妄 <a class="header-anchor" href="#賁之無妄" aria-label="Permalink to “賁之無妄”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>鶴盜我珠，逃於東都。鵠怒追求，郭氏之墟。不見蹤跡，反為禍災。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>詳《豫》之《明夷》。 ○怒，依宋元本，汲古作起，元本此林及《大畜》皆列《恆》下，非。此以巽為盜。</p><h3 id="賁之大畜" tabindex="-1">賁之大畜 <a class="header-anchor" href="#賁之大畜" aria-label="Permalink to “賁之大畜”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>升輿中退，舉事不遂。餔糜毀齒，失其道理。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>震為車、為升，上艮為反震，故曰中退、曰舉事不遂。兌口為餔、為齒，震為糜。糜，至爛之食。乃餔之而齒毀，故曰失道。艮為道，兌毀。○升輿，從局本，宋元本、汲古本皆作外輿。餔，宋元本作哺，義同。糜，從汲古，宋元本作麋。</p><h3 id="賁之頤" tabindex="-1">賁之頤 <a class="header-anchor" href="#賁之頤" aria-label="Permalink to “賁之頤”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>鴻鵠高飛，鳴求其雌。雌來在戶，雄哺嘻嘻。甚獨勞苦，炰鱉膾鯉。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>艮為鴻鵠、為高飛，震為鳴，艮為求，坤為雌、為戶，震為雄、為哺、為嘻嘻。坤役萬物，故曰勞苦。艮為鱉，坤為鯉。○炰，元本作缹，從宋本、汲古。</p><h3 id="賁之大過" tabindex="-1">賁之大過 <a class="header-anchor" href="#賁之大過" aria-label="Permalink to “賁之大過”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>褰衣涉河，水深漬罷。幸賴舟子，濟脫無他。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>詳《剝》之《賁》。 ○罷，音婆，同疲。漬罷，宋本、汲古作漬衣，依元本。</p><h3 id="賁之坎" tabindex="-1">賁之坎 <a class="header-anchor" href="#賁之坎" aria-label="Permalink to “賁之坎”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>虎嚙龍指，泰山之崖。天命不佑，不見其雌。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>互艮為虎，震為龍、為嚙，艮為指，故曰虎嚙龍指。艮為山崖、為天，巽為命，巽伏，故曰天命不佑、故曰不見其雌。</p><h3 id="賁之離" tabindex="-1">賁之離 <a class="header-anchor" href="#賁之離" aria-label="Permalink to “賁之離”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>明不處暗，智不履危。終日卒歲，樂以笑歌。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>離為明智，伏坎為暗、為危，離為日，伏震為歲。艮為卒，震為笑樂。○日，依宋元本，汲古作年。</p><h3 id="賁之鹹" tabindex="-1">賁之鹹 <a class="header-anchor" href="#賁之鹹" aria-label="Permalink to “賁之鹹”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>三足俱行，傾危善僵。六指不便，慁累弟兄。樹柱閡車，失其正當。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>通《損》。震為足、為行，數三，故曰三足。兌為傾危，艮止為僵、為指，乾後天數六，故曰六指。足，指原恃以行動，乃三足行，宜速而善僵。六指宜便利而為累，皆以有餘而不利。坤為車，艮木在上而止，故曰樹柱閡車。坤為失、為慁累。《左傳昭六年》&quot;生不圂賓&quot;，註：慁，猶患也。坤為憂患，亦失傳象。○車，依宋元本，汲古訛居。</p><h3 id="賁之恆" tabindex="-1">賁之恆 <a class="header-anchor" href="#賁之恆" aria-label="Permalink to “賁之恆”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>舍車而徒，亡其駁牛。雖喪白頭，酒以療憂。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>震為徒行、為駁，坤為車、為牛，坤伏，故曰舍車、曰亡牛。乾為頭，巽白，故曰白頭。互大坎為酒、為憂。</p><h3 id="賁之遯" tabindex="-1">賁之遯 <a class="header-anchor" href="#賁之遯" aria-label="Permalink to “賁之遯”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>析薪熾酒，使媒求婦。和合齊宋，薑子悅喜。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>詳《噬嗑》之《家人》。</p><h3 id="賁之大壯" tabindex="-1">賁之大壯 <a class="header-anchor" href="#賁之大壯" aria-label="Permalink to “賁之大壯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>夜視無明，不利賈商。子反笑歡，與市為仇。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>通《觀》。坤為夜，艮為視，坤黑故無明。震為商賈，兌折，故不利。震為子、為歸，故曰子反。震為笑歡，伏巽為市。○不利，汲古作不離，依宋元本。賈商，元本、汲古作商賈，從宋本，與明韻。</p><h3 id="賁之晉" tabindex="-1">賁之晉 <a class="header-anchor" href="#賁之晉" aria-label="Permalink to “賁之晉”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>徒行離車，冒厭泥塗，利以休居。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>震為車、為行，震覆，故曰徒行、曰離車。震為冒，上坎故曰泥塗。艮止故休。○冒厭，宋元本作不冒，依汲古。厭，當也。《史紀高祖紀》&quot;因東遊以厭之&quot;是也。</p><h3 id="賁之明夷" tabindex="-1">賁之明夷 <a class="header-anchor" href="#賁之明夷" aria-label="Permalink to “賁之明夷”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>作室山根，人以為安。一夕崩顛，破我壺餐。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>坎為室，艮為山，艮覆故曰崩。震為人，坎為夕，數一，故曰一夕。坎為破，震為壺。○夕，依汲古，元本作昔。按：此亦或作《賁》象。</p><h3 id="賁之家人" tabindex="-1">賁之家人 <a class="header-anchor" href="#賁之家人" aria-label="Permalink to “賁之家人”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>東山西山，各自言安。雖相登望，竟未同堂。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>此似用《賁》象。艮山、震東、坎西，三至上正反震艮，故曰相登望。震為登，艮為望、為堂，正反艮相背故未同堂。○首句依汲古，宋元本作山東山西。</p><h3 id="賁之睽" tabindex="-1">賁之睽 <a class="header-anchor" href="#賁之睽" aria-label="Permalink to “賁之睽”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>君子在朝，兇言去消。驚駭逐狼，不見雄英。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>此亦用遇卦《賁》象。雄英，依汲古，宋元本作英雄。艮為君子、為朝，震為言，坎險故曰兇言。《左傳》艮為壞，故曰兇言去消。震為驚駭，艮為狼，震為行，故曰逐狼。</p><h3 id="賁之蹇" tabindex="-1">賁之蹇 <a class="header-anchor" href="#賁之蹇" aria-label="Permalink to “賁之蹇”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>隱隱填填，火燒山根。不潤我鄰，獨不蒙恩。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>隱隱，車聲。填填，厚重貌。《莊子馬蹄篇》：&quot;故至德之世，其行填填&quot;是也。此亦用遇卦《賁》象。火在山下，故曰火燒山根。震為鄰，火在坎下，水涸故不潤我鄰。○，依宋元本，汲古訛●。填，宋元本作墳，存左半。汲古作慎，存右半。依兩本證之的是填字。</p><h3 id="賁之解" tabindex="-1">賁之解 <a class="header-anchor" href="#賁之解" aria-label="Permalink to “賁之解”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>南山之蹊，真人所在。德配唐虞，天命為子。保佑歆享，身受大慶。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《豫》。在，汲古作遊，依宋元本。</p><h3 id="賁之損" tabindex="-1">賁之損 <a class="header-anchor" href="#賁之損" aria-label="Permalink to “賁之損”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>龍蛇所聚，大水來處。泱泱霈霈。濙濙濭濭，使我無賴。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>詳《泰》之《豐》。 ○霈，宋元本作濡，依汲古。第四句汲古作淡淡磕磕，依元本。</p><h3 id="賁之益" tabindex="-1">賁之益 <a class="header-anchor" href="#賁之益" aria-label="Permalink to “賁之益”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>旃裘苫蓋，慕德獻服。邊鄙不聳，以安王國。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>坤為裘、為服、為邊鄙、為國，震為毛羽、為旃、為草、為苫，艮為蓋、為獻。不聳者，言夷狄來服而邊鄙不震聳也。○苫蓋，汲古作若闔，聳作悚，均依宋元本。</p><h3 id="賁之夬" tabindex="-1">賁之夬 <a class="header-anchor" href="#賁之夬" aria-label="Permalink to “賁之夬”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>光祀春成，陳寶雞鳴。陽明失道，不能自守，消亡為咎。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>詳《大有》之《井》。 ○光祀，依《大有》之《井》校，宋元、汲古本皆作光體。</p><h3 id="賁之姤" tabindex="-1">賁之姤 <a class="header-anchor" href="#賁之姤" aria-label="Permalink to “賁之姤”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>下泉苞狼，十年無王。荀伯遇時，憂念周京。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>詳《蠱》之《歸妹》。 ○荀，依汲古，元本作郇。</p><h3 id="賁之萃" tabindex="-1">賁之萃 <a class="header-anchor" href="#賁之萃" aria-label="Permalink to “賁之萃”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>仁德不暴，五精就舍。四序允釐，民安其居。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>○序，宋元作牧，依汲古。</p><h3 id="賁之升" tabindex="-1">賁之升 <a class="header-anchor" href="#賁之升" aria-label="Permalink to “賁之升”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>隋和重寶，眾所貪有。相如睨柱，趙王危殆。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>震為珠玉，故曰隋和重寶。隋珠和璧也。坤為眾、為多，震為柱、為王，坤為危殆。○所，宋元本作多，依汲古。《史記藺相如傳》：&quot;相如以璧至秦，察秦人無意與城，乃持璧睨柱，而言曰：臣頭將與璧俱碎&quot;。</p><h3 id="賁之困" tabindex="-1">賁之困 <a class="header-anchor" href="#賁之困" aria-label="Permalink to “賁之困”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>鳳生五雛，長於南城。君子康寧，悅樂身榮。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>互離為鳳，巽卦數五，故曰五雛。兌為雛。伏震為長、為南，艮為郭、為君子，震為康樂。</p><h3 id="賁之井" tabindex="-1">賁之井 <a class="header-anchor" href="#賁之井" aria-label="Permalink to “賁之井”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>二人為旅，俱歸北海。入門上堂，拜謁王母。勞賜我酒，女功悅喜。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>通《噬嗑》。震為人，正覆艮，故曰二人。坎為北、為海，震為歸，故俱歸北海。艮為門、為堂，巽入。震為王，巽為母，艮為拜，故曰拜謁王母。坎為酒，兌為女、為悅喜。○旅，宋元本作侶，依汲古。悅喜，汲古作不喜，非，依宋元本。</p><h3 id="賁之革" tabindex="-1">賁之革 <a class="header-anchor" href="#賁之革" aria-label="Permalink to “賁之革”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>逐憂去殃，洿泥生梁，下田為王。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>○通《蒙》。震為逐，坤為憂、為殃，坤坎皆為水，故曰洿泥。震為生、為粱，坤為下、為田，震為王。○去，汲古作除，茲依宋元本。</p><h3 id="賁之鼎" tabindex="-1">賁之鼎 <a class="header-anchor" href="#賁之鼎" aria-label="Permalink to “賁之鼎”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>東門之壇，茹藘在阪。禮義不行，與我心反。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。震東，互艮為門、為壇，震為茹藘。《毛傳》茹藘，茅也。艮為阪，坤為禮義，坤閉故不行。坤為我、為心。《鼎》巽為心，初至五正反巽，故曰心反。黃丕烈雲：正義雲：徧檢諸本皆作壇，今定本作墠，釋文雲：&quot;壇者，音善，依字當作墠&quot;云云，今《易林》正作壇，可見作《易林》時仍是壇字，與孔疏合。今作堚，似是，實非是，《易林》可證經誤字。○壇，汲古作墠，依宋元本。○按：此詩毛以為刺淫奔，焦以為賢人居鄭東門，君若臣不以禮致之，室近人遠也。義較毛長。</p><h3 id="賁之震" tabindex="-1">賁之震 <a class="header-anchor" href="#賁之震" aria-label="Permalink to “賁之震”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>鳧遇稻蘆，甘樂暎雖驅不去。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>艮為鳧，震為蘆稻。《廣韻》、《集韻》皆音礦，《玉篇》：&quot;大麥也&quot;。伏巽為魚、為暎震歸，故不去。○蘆，宋元本作廬，今依汲古。</p><h3 id="賁之艮" tabindex="-1">賁之艮 <a class="header-anchor" href="#賁之艮" aria-label="Permalink to “賁之艮”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>清人高子，久屯外野。逍遙不歸，思我慈母。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《睽》。 ○依《師》之《睽》校作慈母，各本皆作君母。又各本多&quot;公子奉請，王孫嘉許&quot;二句，與上文語意不合，亦依《師》之《睽》校刪。</p><h3 id="賁之漸" tabindex="-1">賁之漸 <a class="header-anchor" href="#賁之漸" aria-label="Permalink to “賁之漸”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>讒佞所言，語不成全。虎狼之患，不為我殘。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>伏震為言，伏兌亦為言，故曰讒佞。坎破，故語不成全。艮為虎狼，坎為患、為殘，巽順，故不殘。○佞，汲古作人，依宋元本。</p><h3 id="賁之歸妹" tabindex="-1">賁之歸妹 <a class="header-anchor" href="#賁之歸妹" aria-label="Permalink to “賁之歸妹”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>張羅捕鳩，兔麗其災。雌雄俱得，為網所賊。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>互離為羅網、為鳩，震為兔，坎為災。麗，《左傳宣十二年》&quot;射麋麗龜&quot;註：麗，著也，言張羅本以捕鳩，不意兔當其災而被捕也。卦震兔，居離網中，而兌為毀折，故有此象。坎雄離雌。坎為賊。○兔，各本皆作鳥，依《歸妹》之《節》校改。</p><h3 id="賁之豐" tabindex="-1">賁之豐 <a class="header-anchor" href="#賁之豐" aria-label="Permalink to “賁之豐”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>安仁尚德，東鄰慕義，來安吾國。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>震為仁德，離為東鄰，伏艮為國、為安。</p><h3 id="賁之旅" tabindex="-1">賁之旅 <a class="header-anchor" href="#賁之旅" aria-label="Permalink to “賁之旅”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>猾醜假誠，前後相違。言如鱉咳，語不可知。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>艮為鱉，兌為言、為咳、為語，巽伏故不知。又離為惡人、為猾醜，坎為信、為誠，假誠者，言心本猾而託為誠實，故前後相違。因二至五正反兌相背，故語不信實。困有言不信義同也。○假，宋元本作如，依汲古。又按前後相違亦謂二至五正反兌相背。</p><h3 id="賁之巽" tabindex="-1">賁之巽 <a class="header-anchor" href="#賁之巽" aria-label="Permalink to “賁之巽”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>懷璧越鄉，不可遠行。蔡侯兩裘，久苦流離。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>伏震為璧，艮為鄉，震為行、為蔡、為諸侯、為裘。重震，故曰兩裘。《左傳定二年》：蔡侯如楚，有兩裘，一獻楚王，一自御。子常求之，不與，留之三年。</p><h3 id="賁之兌" tabindex="-1">賁之兌 <a class="header-anchor" href="#賁之兌" aria-label="Permalink to “賁之兌”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>伯氏歸國，多所恨惑。車傾蓋亡，身常驚惶。乃得其願，雌雄相從。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《屯》伏震為伯。</p><h3 id="賁之渙" tabindex="-1">賁之渙 <a class="header-anchor" href="#賁之渙" aria-label="Permalink to “賁之渙”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>火石相得，乾無潤澤。利少囊縮，祇益促迫。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>互艮為火、為石，皆燥無潤澤，故曰相得。巽為利，坤為囊，中祇二陰爻，故曰囊縮，曰促迫。○汲古無第四句，非，依宋元本。</p><h3 id="賁之節" tabindex="-1">賁之節 <a class="header-anchor" href="#賁之節" aria-label="Permalink to “賁之節”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>君明聖哲，鳴呼其友。顯德之徒，可以禮仕。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>震為君，艮為明，坎為聖哲，震為鳴，艮為友，為顯，為仕。○明，宋元本作知，依汲古。</p><h3 id="賁之中孚" tabindex="-1">賁之中孚 <a class="header-anchor" href="#賁之中孚" aria-label="Permalink to “賁之中孚”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>騎豚逐羊，不見所望。徑涉虎廬，亡豚失羊。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>詳乾之蹇。○亡豚，宋元本作亡羝，從汲古。此以巽為豚。</p><h3 id="賁之小過" tabindex="-1">賁之小過 <a class="header-anchor" href="#賁之小過" aria-label="Permalink to “賁之小過”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>玄黃瘣隤，行者勞疲。役夫憔悴，處子畏哀。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>震為玄黃、為行，兌折，故曰瘣隤。瘣隤，病也。互大坎為勞、為役，震為夫，巽為震妻而伏，故曰處子。坎為畏哀也。○瘣隤，依宋元本。《說文》：&quot;瘣，病也&quot;，音回，汲古作虺隤，與今本詩合。虺瘣音同。又釋文雲《說文》作隤，《爾雅》同。亦音回，訓病，然則瘣、、虺三字音義皆同，特焦作瘣，與毛許異耳。畏哀，汲古作猥衰，依元本。</p><h3 id="賁之既濟" tabindex="-1">賁之既濟 <a class="header-anchor" href="#賁之既濟" aria-label="Permalink to “賁之既濟”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>右手掩目，不見長叔。失其所得，悔吝相仍。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>此用《賁》象。艮手離目，震長艮叔，坎隱故不見。</p><h3 id="賁之未濟" tabindex="-1">賁之未濟 <a class="header-anchor" href="#賁之未濟" aria-label="Permalink to “賁之未濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>免冠進賢，步出朝門。儀體不正，賊孽為患。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《兌》。</p>',317)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
